function AuditPage({membership,search}:{membership:Membership;search:string}) { const {rows,loading,error,refresh}=useDbRows('audit_events',membership,{order:'occurred_at'});const shown=rows.filter(r=>!search||`${r.table_name} ${r.action} ${r.record_id??''}`.toLowerCase().includes(search.toLowerCase()));return <><PageHeading eyebrow="GOVERNANCE / AUDIT" title="تاریخچه تغییرات" description="رویدادهای داده‌ای که در جدول‌های اصلی ثبت شده‌اند؛ برای مالک و مدیر مجموعه." action={<Button variant="soft" onClick={()=>void refresh()}><Activity size={15}/> تازه‌سازی</Button>}/>{error&&<InlineError error={error} retry={()=>void refresh()}/>}<section className="panel entity-panel">{loading?<div className="panel-loading"><span className="spinner small"/></div>:shown.length?<DataTable rows={shown} columns={[{key:'occurred_at',label:'زمان',render:r=>dateTimeFa(String(r.occurred_at??''))},{key:'actor_id',label:'کاربر',render:r=>r.actor_id?String(r.actor_id).slice(0,8):'سیستم'},{key:'table_name',label:'بخش'},{key:'action',label:'عملیات'},{key:'record_id',label:'شناسه رکورد',render:r=><code>{String(r.record_id??'—').slice(0,12)}</code>},{key:'changes',label:'خلاصه تغییرات',render:r=><code className="changes-code">{JSON.stringify(r.changes??{})}</code>} ]}/>:<EmptyState title="رویدادی ثبت نشده" description="پس از ایجاد یا تغییر رکوردهای اصلی، تاریخچه از طریق trigger دیتابیس تکمیل می‌شود." icon={Activity}/>}</section></>; }
function CustomerCatalog({membership}:{membership:Membership}) {
 const {user}=useAuth();const [items,setItems]=useState<Row[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [quantities,setQuantities]=useState<Record<string,string>>({});const [busy,setBusy]=useState('');const [notice,setNotice]=useState('');
 const load=async()=>{if(!supabase||!membership.customer_id)return;setLoading(true);setError('');const {data,error:e}=await supabase.from('price_agreements').select('id,product_id,unit_price,min_qty,valid_from,valid_to,products(id,name,sku,unit,kind,shelf_life_days,storage_note)').eq('company_id',membership.company_id).eq('customer_id',membership.customer_id).lte('valid_from',new Date().toISOString().slice(0,10)).order('valid_from',{ascending:false}).limit(200);if(e)setError(e.message);setItems((data??[]) as Row[]);setLoading(false);};useEffect(()=>{void load()},[membership.company_id,membership.customer_id]);
 const orderNow=async(agreement:Row)=>{if(!supabase||!membership.customer_id||!user)return;const p=agreement.products as any;if(!p?.id)return;const qty=Number(quantities[String(agreement.id)]??agreement.min_qty);if(!Number.isFinite(qty)||qty<Number(agreement.min_qty)){setError(`حداقل مقدار مجاز برای «${p.name}» برابر ${numberFa(String(agreement.min_qty))} است.`);return;}setBusy(String(agreement.id));setError('');setNotice('');const {data:o,error:oe}=await supabase.from('orders').insert({company_id:membership.company_id,customer_id:membership.customer_id,status:'draft',created_by:user.id}).select('id,reference').single();if(oe){setError(oe.message);setBusy('');return;}const {error:ie}=await supabase.from('order_items').insert({company_id:membership.company_id,order_id:o.id,product_id:p.id,quantity:qty,unit_price:Number(agreement.unit_price)});if(ie){await supabase.from('orders').update({status:'cancelled'}).eq('id',o.id).eq('company_id',membership.company_id);setError(ie.message);}else setNotice(`پیش‌نویس سفارش ${o.reference} ساخته شد. برای نهایی شدن، وضعیت را از بخش «سفارش‌های من» ارسال کن.`);setBusy('');};
 return <><PageHeading eyebrow="CUSTOMER COMMERCE / CATALOG" title="کاتالوگ اختصاصی شما" description="فقط محصولاتی نمایش داده می‌شوند که برای حساب سازمانی شما قرارداد قیمت فعال دارند." action={<Button variant="soft" onClick={()=>void load()}>تازه‌سازی کاتالوگ</Button>}/>{error&&<InlineError error={error} retry={()=>void load()}/>}{notice&&<div className="form-success notice-wide"><CheckCircle2 size={17}/>{notice}<Link to="/app/my-orders">مشاهده سفارش‌ها <ArrowLeft size={14}/></Link></div>}{loading?<div className="panel-loading"><span className="spinner small"/></div>:items.length?<div className="catalog-grid">{items.filter(a=>(a.products as any)?.id&&(!a.valid_to||String(a.valid_to)>=new Date().toISOString().slice(0,10))).map(a=>{const p=a.products as any;return <article className="catalog-card" key={String(a.id)}><div className={`catalog-art ${p.kind==='eggs'?'eggs-art':p.kind==='meat'?'meat-art':'other-art'}`}><span>{p.kind==='eggs'?'تخم بلدرچین':p.kind==='meat'?'گوشت بلدرچین':'محصول'}</span><Boxes size={44}/><small>{String(p.sku??'')}</small></div><div className="catalog-details"><div className="catalog-product-meta"><span>قیمت توافق‌شده حساب شما</span><Badge value="active"/></div><h3>{String(p.name)}</h3><p>{String(p.unit)}{p.shelf_life_days?` · ماندگاری ثبت‌شده ${numberFa(p.shelf_life_days)} روز`:''}</p>{p.storage_note&&<small className="catalog-storage">{String(p.storage_note)}</small>}<div className="catalog-price"><b>{moneyFa(String(a.unit_price))}</b><small>حداقل مقدار: {numberFa(String(a.min_qty))} {String(p.unit)}</small></div><div className="catalog-buy-row"><label>مقدار<input type="number" min={Number(a.min_qty)} step="0.001" value={quantities[String(a.id)]??String(a.min_qty)} onChange={e=>setQuantities({...quantities,[String(a.id)]:e.target.value})} dir="ltr"/></label><Button onClick={()=>void orderNow(a)} disabled={busy===String(a.id)}>{busy===String(a.id)?'در حال ثبت…':<><Plus size={15}/> افزودن به سفارش</>}</Button></div></div></article>})}</div>:<section className="panel"><EmptyState title="کاتالوگ اختصاصی هنوز آماده نیست" description="برای حساب شما قرارداد قیمت فعال پیدا نشد. از مسئول فروش بخواه محصول و شرایط قیمت را در پنل مدیریت ثبت کند." icon={Package}/></section>}</>;
}
function CustomerOrders({membership,search}:{membership:Membership;search:string}) {
 const [orders,setOrders]=useState<Row[]>([]);const [invoices,setInvoices]=useState<Row[]>([]);const [shipments,setShipments]=useState<Row[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [busy,setBusy]=useState('');
 const load=async()=>{if(!supabase)return;setLoading(true);const [o,i,s]=await Promise.all([supabase.from('orders').select('id,reference,status,requested_delivery,delivery_address,created_at,order_items(quantity,unit_price,products(name,unit))').eq('company_id',membership.company_id).eq('customer_id',membership.customer_id??'').order('created_at',{ascending:false}).limit(250),supabase.from('invoices').select('*').eq('company_id',membership.company_id).eq('customer_id',membership.customer_id??'').order('created_at',{ascending:false}).limit(250),supabase.from('shipments').select('id,order_id,stage,planned_departure,departed_at,delivered_at,vehicle').eq('company_id',membership.company_id).order('created_at',{ascending:false}).limit(250)]);const err=o.error??i.error??s.error;if(err)setError(err.message);setOrders((o.data??[]) as Row[]);setInvoices((i.data??[]) as Row[]);setShipments((s.data??[]) as Row[]);setLoading(false);};useEffect(()=>{void load()},[membership.company_id,membership.customer_id]);
 const submit=async(o:Row)=>{if(!supabase||!window.confirm(`سفارش ${String(o.reference)} برای بررسی به مجموعه ارسال شود؟`))return;setBusy(String(o.id));const {error:e}=await supabase.from('orders').update({status:'submitted'}).eq('id',String(o.id)).eq('company_id',membership.company_id);if(e)setError(e.message);else await load();setBusy('');};const shown=orders.filter(o=>!search||`${o.reference} ${o.status}`.toLowerCase().includes(search.toLowerCase()));
 return <><PageHeading eyebrow="CUSTOMER COMMERCE / ORDERS" title="سفارش‌های سازمانی شما" description="پیش‌نویس‌ها، وضعیت پردازش و موعد تحویل از داده واقعی سیستم خوانده می‌شوند." action={<Button variant="soft" onClick={()=>void load()}>تازه‌سازی</Button>}/>{error&&<InlineError error={error} retry={()=>void load()}/>}<section className="panel entity-panel"><div className="panel-heading"><div><span className="section-number">۰۱</span><div><h3>سفارش‌ها</h3><p>ارسال پیش‌نویس به‌معنای تأیید تأمین نیست.</p></div></div><Link to="/app/catalog" className="link-action">رفتن به کاتالوگ <ArrowLeft size={14}/></Link></div>{loading?<div className="panel-loading"><span className="spinner small"/></div>:shown.length?<div className="customer-order-stack">{shown.map(o=><article className="customer-order-card" key={String(o.id)}><div className="customer-order-main"><span className="order-symbol"><FileText size={19}/></span><div><b>{String(o.reference)}</b><small>{dateTimeFa(String(o.created_at??''))}</small><div className="order-items-inline">{((o.order_items??[]) as any[]).map((it,i)=><span key={i}>{String(it.products?.name??'محصول')} · {numberFa(String(it.quantity))} {String(it.products?.unit??'')}</span>)}</div></div></div><div className="customer-order-status"><Badge value={o.status}/><small>تحویل درخواستی: {dateFa(String(o.requested_delivery??''))}</small></div>{o.status==='draft'&&<Button onClick={()=>void submit(o)} disabled={busy===String(o.id)}>{busy===String(o.id)?'در حال ارسال…':'ارسال برای بررسی'} <ArrowLeft size={14}/></Button>}</article>)}</div>:<EmptyState title="سفارشی وجود ندارد" description="از کاتالوگ اختصاصی اولین سفارش خود را بساز." icon={FileText}/>}</section><section className="panel recent-panel"><div className="panel-heading"><div><span className="section-number">۰۲</span><div><h3>پیگیری ارسال</h3><p>مرحله‌ای که عملیات ثبت کرده است</p></div></div></div>{shipments.filter(s=>orders.some(o=>o.id===s.order_id)).length?<DataTable rows={shipments.filter(s=>orders.some(o=>o.id===s.order_id))} columns={[{key:'id',label:'محموله',render:r=><code>{String(r.id).slice(0,8).toUpperCase()}</code>},{key:'order_id',label:'سفارش',render:r=>String(orders.find(o=>o.id===r.order_id)?.reference ?? '—')},{key:'stage',label:'مرحله',render:r=><Badge value={r.stage}/>},{key:'planned_departure',label:'زمان برنامه‌ریزی',render:r=>dateTimeFa(String(r.planned_departure??''))},{key:'delivered_at',label:'تحویل',render:r=>dateTimeFa(String(r.delivered_at??''))}]}/>:<EmptyState title="ارسالی در جریان نیست" description="پس از تخصیص محموله از سوی تیم عملیات، وضعیت در این بخش نمایش داده می‌شود." icon={Truck}/>}</section><section className="panel recent-panel"><div className="panel-heading"><div><span className="section-number">۰۳</span><div><h3>فاکتورها</h3><p>سوابق فاکتور در حساب سازمانی</p></div></div></div>{invoices.length?<DataTable rows={invoices} columns={[{key:'reference',label:'شماره فاکتور'},{key:'amount',label:'مبلغ',render:r=>moneyFa(String(r.amount))},{key:'paid_amount',label:'پرداخت‌شده',render:r=>moneyFa(String(r.paid_amount))},{key:'due_date',label:'سررسید'},{key:'status',label:'وضعیت',render:r=><Badge value={r.status}/>}]}/>:<EmptyState title="فاکتوری صادر نشده" description="فاکتور پس از پردازش تجاری توسط تیم مجاز صادر می‌شود." icon={CreditCard}/>}</section></>;
}
